solution.javascript:
function classerEtoiles(etoiles) {
  const copie = [...etoiles];
  copie.sort((a, b) => {
    if (a.eclat !== b.eclat) {
      return b.eclat - a.eclat;
    }
    if (a.distance !== b.distance) {
      return a.distance - b.distance;
    }
    return a.nom < b.nom ? -1 : 1;
  });
  return copie.map((etoile) => etoile.nom);
}

