solution.javascript:
function classerAvecExAequo(etoiles, n) {
  const visibles = etoiles.filter((e) => e.eclat > 0);
  const tri = [...visibles].sort((a, b) => b.eclat - a.eclat || a.distance - b.distance);
  const resultat = [];
  let rang = 0;
  for (let i = 0; i < tri.length; i++) {
    const different =
      i === 0 || tri[i].eclat !== tri[i - 1].eclat || tri[i].distance !== tri[i - 1].distance;
    if (different) {
      rang = i + 1;
    }
    if (rang > n) {
      break;
    }
    resultat.push([tri[i].nom, rang]);
  }
  return resultat;
}

